-- ============================================
-- LUMA — Thème 15 : LONG 2/3 x4 — Se perdre et retrouver son chemin en interagissant avec plusieurs habitants
-- ============================================


update scenarios set content = '{"characters": {"dogwalker": "le promeneur de chien", "shopkeeper": "le commerçant", "helper1": "aide 1", "helper2": "aide 2", "teenager": "un adolescent"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "(Your phone died, and you realize you''re deep in an unfamiliar residential neighborhood.)", "text_fr": "(Votre téléphone est mort, et vous réalisez que vous êtes en plein cœur d''un quartier résidentiel inconnu.)", "choices": [{"text": "(Approach someone walking their dog for directions.)", "text_fr": "(Approche quelqu''un promenant son chien pour demander le chemin.)", "next": "n2"}, {"text": "(Look for a shop where you could ask for help.)", "text_fr": "(Cherche une boutique où tu pourrais demander de l''aide.)", "next": "n2b"}]}, "n2": {"speaker": "dogwalker", "text": "Lost, are you? Happens to tourists around here all the time, ha.", "text_fr": "Perdu, hein ? Ça arrive tout le temps aux touristes par ici, ha.", "choices": [{"text": "Yes, completely! I''m trying to get back to central London.", "text_fr": "Oui, complètement ! J''essaie de retourner dans le centre de Londres.", "next": "n3"}]}, "n2b": {"speaker": "shopkeeper", "text": "You look a bit lost, love. Where are you trying to get to?", "text_fr": "Vous semblez un peu perdu, chéri. Vous essayez d''aller où ?", "choices": [{"text": "Central London, but I''m honestly not sure which direction that is.", "text_fr": "Le centre de Londres, mais honnêtement je sais pas dans quelle direction c''est.", "next": "n3"}]}, "n3": {"speaker": "helper1", "text": "Ah, you''re a fair way out! Head down this road, then take a left at the church.", "text_fr": "Ah, vous êtes assez loin ! Descendez cette route, puis tournez à gauche à l''église.", "choices": [{"text": "Thank you so much, I really appreciate the help.", "text_fr": "Merci beaucoup, j''apprécie vraiment l''aide.", "next": "n4"}]}, "n4": {"speaker": "you_thought", "text": "(Following the directions, you reach the church, but the street layout gets confusing again.)", "text_fr": "(En suivant les indications, vous atteignez l''église, mais la disposition des rues redevient confuse.)", "choices": [{"text": "(Ask another passerby for further clarification.)", "text_fr": "(Demande à un autre passant pour plus de clarification.)", "next": "n5"}]}, "n5": {"speaker": "helper2", "text": "Oh, this area''s a maze if you don''t know it! You want the second right after this.", "text_fr": "Oh, ce quartier est un labyrinthe si on le connaît pas ! Vous voulez la deuxième à droite après ça.", "choices": [{"text": "Second right, got it. Thank you for clarifying!", "text_fr": "Deuxième à droite, compris. Merci d''avoir clarifié !", "next": "n6"}]}, "n6": {"speaker": "you_thought", "text": "(You follow the new directions, but soon find yourself at a confusing five-way intersection.)", "text_fr": "(Vous suivez les nouvelles indications, mais vous vous retrouvez bientôt à un carrefour confus à cinq voies.)", "choices": [{"text": "(Approach a group of teenagers hanging around, hoping they know the area well.)", "text_fr": "(Approche un groupe d''adolescents qui traînent, espérant qu''ils connaissent bien le quartier.)", "next": "n7"}]}, "n7": {"speaker": "teenager", "text": "Central London? Easy, just follow this road straight for like ten minutes, you''ll see signs.", "text_fr": "Le centre de Londres ? Facile, suivez juste cette route tout droit pendant genre dix minutes, vous verrez des panneaux.", "choices": [{"text": "Perfect, straightforward directions for once! Thank you.", "text_fr": "Parfait, des indications simples pour une fois ! Merci.", "next": "n8"}]}, "n8": {"speaker": "you_thought", "text": "(Sure enough, after ten minutes, familiar landmarks finally come into view.)", "text_fr": "(Effectivement, après dix minutes, des points de repère familiers apparaissent enfin.)", "choices": [{"text": "(Feel a wave of relief seeing the London skyline again.)", "text_fr": "(Ressens une vague de soulagement en revoyant l''horizon de Londres.)", "next": "n9"}]}, "n9": {"speaker": "you_thought", "text": "(You finally recognize the street leading back to your hotel.)", "text_fr": "(Vous reconnaissez enfin la rue qui mène à votre hôtel.)", "choices": [{"text": "(Walk the final stretch, relieved and oddly proud of navigating without a phone.)", "text_fr": "(Marche le dernier tronçon, soulagé et étrangement fier d''avoir navigué sans téléphone.)", "next": "n10"}]}, "n10": {"speaker": "you_thought", "text": "(Despite the stress, you realize you met several kind strangers along the way.)", "text_fr": "(Malgré le stress, vous réalisez que vous avez rencontré plusieurs inconnus gentils en chemin.)", "choices": [{"text": "(Reflect on how this unplanned adventure revealed the kindness of Londoners.)", "text_fr": "(Réfléchis à comment cette aventure imprévue a révélé la gentillesse des Londoniens.)", "next": "end_found"}]}, "end_found": {"speaker": "you_thought", "text": "(Getting lost turned into an unexpectedly heartwarming afternoon.)", "text_fr": "(Se perdre s''est transformé en un après-midi étonnamment réconfortant.)", "end": true, "ending_label": "Perdu puis retrouvé grâce à la gentillesse des habitants 🗺️❤️"}}}'::jsonb, is_playable = true
where title = 'Se perdre et retrouver son chemin en interagissant avec plusieurs habitants'
  and theme_id = (select id from scenario_themes where position = 15 and language_id = (select id from languages where code = 'en'));
